import {localDate} from './history-model.js';
import {prepareComments} from './import-review.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={mode:'paste',raw:'',brand:'',date:localDate(),product:'',platform:'未标注',split:'line',dedup:true,preview:null,images:[],busy:false,status:'',cancel:false,worker:null,ocr:false};
const $=s=>document.querySelector(s);
export function importPanel(){return `<section class="card quick-import"><div class="import-tabs" role="group" aria-label="评论导入方式"><button data-import-mode="paste" class="${state.mode==='paste'?'selected':''}">▤ 直接粘贴评论</button><button data-import-mode="image" class="${state.mode==='image'?'selected':''}">▧ 上传评论截图</button></div><div class="import-intro"><h2>${state.mode==='paste'?'复制评论，就能开始洞察。':'评论区截个图，让文字自己进来。'}</h2><p>${state.mode==='paste'?'粘贴一批消费者反馈，预览并勾选需要分析的内容，无需整理表格。':'支持简体中文与英文截图，本地 OCR 识别后请核对文字、评论边界和昵称。'}</p></div>${state.mode==='image'?`<div class="screenshot-box"><label class="image-picker" for="screenshots">＋ 选择评论截图<input id="screenshots" type="file" accept="image/png,image/jpeg,image/webp" multiple hidden></label><span>PNG / JPG / WebP · 最多 5 张 · 每张 ≤ 10 MB · 合计 ≤ 20 MB</span></div><div class="image-previews">${state.images.map((x,i)=>`<figure><img src="${x.url}" alt="待识别截图 ${i+1}"><figcaption>${esc(x.file.name)}</figcaption></figure>`).join('')}</div><div class="ocr-controls"><button class="primary" id="ocr-start" ${state.busy||!state.images.length?'disabled':''}>${state.busy?'识别中…':'识别截图中的文字'}</button><button id="ocr-cancel" ${state.busy?'':'hidden'}>停止识别</button><span id="ocr-status" role="status" aria-live="polite">${esc(state.status)}</span></div><p class="muted">首次使用需加载本地中文识别资源；截图留在当前浏览器。识别可能有错字或错分行，请裁掉无关区域，保留清晰评论。结果会追加到下方文本框。</p>`:''}<div class="import-meta"><label>品牌名称（必填）<input id="paste-brand" maxlength="100" value="${esc(state.brand)}" placeholder="例如：伊菲丹" required></label><label>采集日期<input id="paste-date" type="date" value="${state.date}" required></label></div><div class="import-meta"><label>产品名称（选填）<input id="paste-product" maxlength="100" value="${esc(state.product)}" placeholder="例如：某品牌水润精华"></label><label>平台来源<select id="paste-platform">${['未标注','小红书','抖音','微博','淘宝 / 天猫','京东','其他'].map(v=>`<option ${state.platform===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="paste-label" for="paste-text">${state.ocr?'识别结果 · 请核对并编辑':'评论文本'}<small>最多 20 万字；不会自动抓取链接中的评论</small></label><textarea id="paste-text" maxlength="200000" rows="8" placeholder="将复制的评论粘贴到这里，例如：&#10;保湿很好用，吸收快。&#10;价格有点高，而且用着搓泥。&#10;&#10;默认每行一条；一条评论有多行时，可选择按空行分隔。">${esc(state.raw)}</textarea><div class="paste-options"><label>评论分隔方式<select id="paste-split"><option value="line" ${state.split==='line'?'selected':''}>每行一条评论</option><option value="paragraph" ${state.split==='paragraph'?'selected':''}>空行分隔，多行合为一条</option></select></label><label class="check-option"><input id="paste-dedup" type="checkbox" ${state.dedup?'checked':''}>默认排除重复评论（可恢复）</label></div><div class="paste-actions"><button class="primary" id="paste-preview" ${state.busy?'disabled':''}>预览与清理 →</button><span>先预览，再分析。昵称无法可靠自动识别，请手动取消勾选。</span></div><p id="paste-error" role="alert"></p><div id="paste-review"></div></section>`}
function refreshReview(){const el=$('#paste-review');if(!el)return;const p=state.preview;if(!p){el.innerHTML='';return;}const n=p.items.filter(x=>x.keep).length;el.innerHTML=`<div class="review-head"><h3>核对将用于分析的评论</h3><p>已去空白 ${p.blanks} 处 · 重复 ${p.duplicates} 条 · 疑似时间 / 界面文字 ${p.metadata} 条</p><p>每个勾选项将作为一条评论。发现拆行或错字，请编辑上方文本后重新预览。</p></div><div class="review-actions"><button id="keep-all">全部保留</button><button id="keep-none">全部取消</button><strong id="review-count">已选 ${n} / ${p.items.length} 条</strong></div><div class="review-list">${p.items.map((x,i)=>`<label class="review-item"><input type="checkbox" data-review-index="${i}" ${x.keep?'checked':''}><span class="review-index">${i+1}</span><span class="review-text">${esc(x.text)}</span>${x.duplicate?'<small>重复</small>':''}${x.noise?'<small>疑似非评论</small>':''}</label>`).join('')}</div><div class="paste-actions"><button class="primary" id="paste-commit" ${n?'':'disabled'}>分析并保存记录 →</button><span>自动保存为新的分析记录，已保存的历史记录会保留。</span></div>`;
const update=()=>{const n=p.items.filter(x=>x.keep).length;$('#review-count').textContent=`已选 ${n} / ${p.items.length} 条`;$('#paste-commit').disabled=!n};el.querySelectorAll('[data-review-index]').forEach(c=>c.onchange=()=>{p.items[Number(c.dataset.reviewIndex)].keep=c.checked;update()});$('#keep-all').onclick=()=>{p.items.forEach(x=>x.keep=true);refreshReview();bindCommit()};$('#keep-none').onclick=()=>{p.items.forEach(x=>x.keep=false);refreshReview();bindCommit()};bindCommit();}
let commitCallback,renderCallback;
function bindCommit(){if($('#paste-commit'))$('#paste-commit').onclick=()=>{const items=state.preview?.items.filter(x=>x.keep)||[];if(!items.length)return;if(!state.brand.trim()){document.querySelector('#paste-error').textContent='请填写品牌名称，便于保存到专门的品牌档案。';document.querySelector('#paste-brand').focus();return;}if(!state.date){document.querySelector('#paste-error').textContent='请选择采集日期。';return;}const source=`${state.ocr?'截图识别后人工核对':'手动粘贴'} · ${state.platform}`;commitCallback(items.map(x=>({产品:state.product.trim()||'未标注产品',评论:x.text,来源:state.platform})),source,{brand:state.brand.trim(),collectedAt:state.date})}}
function invalidate(){state.preview=null;refreshReview();if($('#paste-error'))$('#paste-error').textContent=''}
function status(message){state.status=message;if($('#ocr-status'))$('#ocr-status').textContent=message}
async function loadOcr(){if(window.Tesseract)return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/ocr/tesseract.min.js';s.onload=resolve;s.onerror=()=>{s.remove();reject(Error('识别资源加载失败，请检查网络后重试。'))};document.head.append(s)})}
function timeout(p,ms){let timer;return Promise.race([p,new Promise((_,reject)=>timer=setTimeout(()=>reject(Error('识别超时，请使用更小、更清晰的截图重试。')),ms))]).finally(()=>clearTimeout(timer))}
async function recognize(){if(state.busy||!state.images.length)return;state.busy=true;state.cancel=false;invalidate();renderCallback();let worker;let index=0;try{status('正在加载本地文字识别引擎…');await timeout(loadOcr(),45000);if(state.cancel)return;
let fail;const failure=new Promise((_,reject)=>fail=reject);state.stop=()=>fail(Error('已停止识别。'));failure.catch(()=>{});
const workerPromise=window.Tesseract.createWorker(['chi_sim'],1,{workerPath:new URL('vendor/ocr/worker.min.js',location.href).href,corePath:new URL('vendor/ocr/',location.href).href,langPath:new URL('vendor/ocr/',location.href).href.replace(/\/$/,''),gzip:false,logger:m=>{if(!state.cancel)status(m.status==='recognizing text'?`正在识别第 ${index+1} / ${state.images.length} 张 · ${Math.round((m.progress||0)*100)}%`:'正在准备识别资源…')},errorHandler:e=>fail(Error('文字识别失败，请检查图片格式或刷新后重试。'))});
workerPromise.then(w=>{if(state.cancel)w.terminate()}).catch(()=>{});worker=await timeout(Promise.race([workerPromise,failure]),90000);state.worker=worker;if(state.cancel)return;await worker.setParameters({tessedit_pageseg_mode:'11',preserve_interword_spaces:'0'});
let count=0;for(index=0;index<state.images.length;index++){if(state.cancel)break;const img=state.images[index];const bitmap=await createImageBitmap(img.file);const scale=Math.min(2,Math.max(1,1600/bitmap.width),Math.sqrt(8000000/(bitmap.width*bitmap.height)));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const result=await timeout(Promise.race([worker.recognize(canvas),failure]),120000);if(state.cancel)break;const text=result.data.text.trim().replace(/([\u3400-\u9fff]) +(?=[\u3400-\u9fff])/g,'$1');if(text){state.raw=(state.raw?state.raw+'\n\n':'')+text;state.ocr=true;count++;}canvas.width=0;canvas.height=0;}
status(state.cancel?'已停止；已完成的识别文字保留在文本框。':count?`已识别 ${count} 张截图。请核对下方文字，再点击“预览与清理”。`:'没有识别到文字，请上传清晰的评论区截图。');
}catch(e){const cancelled=state.cancel;state.cancel=true;status(cancelled?'已停止；已完成的识别文字已保留。':e.message||'识别失败，请重试。')}finally{if(worker)await worker.terminate().catch(()=>{});state.worker=null;state.stop=null;state.busy=false;if(state.cancel&&state.status.startsWith('正在停止'))status('已停止识别。');renderCallback();}}
export function bindImport(onCommit,onRender){commitCallback=onCommit;renderCallback=onRender;if(!$('#paste-text'))return;
document.querySelectorAll('[data-import-mode]').forEach(b=>{b.disabled=state.busy;b.onclick=()=>{state.mode=b.dataset.importMode;onRender()}});
$('#paste-text').disabled=state.busy;$('#paste-text').oninput=e=>{state.raw=e.target.value;invalidate()};$('#paste-brand').oninput=e=>state.brand=e.target.value;$('#paste-date').onchange=e=>state.date=e.target.value;$('#paste-product').oninput=e=>state.product=e.target.value;$('#paste-platform').onchange=e=>state.platform=e.target.value;$('#paste-split').onchange=e=>{state.split=e.target.value;invalidate()};$('#paste-dedup').onchange=e=>{state.dedup=e.target.checked;invalidate()};$('#paste-preview').onclick=()=>{try{state.preview=prepareComments(state.raw,state.split,state.dedup);if(!state.preview.items.length)throw Error('请先粘贴评论或识别截图。');$('#paste-error').textContent='';refreshReview()}catch(e){state.preview=null;refreshReview();$('#paste-error').textContent=e.message}};
if($('#screenshots')){$('#screenshots').disabled=state.busy;$('#screenshots').onchange=e=>{const files=[...e.target.files];if(!files.length)return;let error='';if(files.length>5)error='最多选择 5 张截图。';else if(files.some(f=>!['image/png','image/jpeg','image/webp'].includes(f.type)))error='请使用 PNG、JPG 或 WebP 图片。';else if(files.some(f=>f.size>10*1024*1024)||files.reduce((s,f)=>s+f.size,0)>20*1024*1024)error='每张图片最多 10 MB，合计最多 20 MB。';if(error){status(error);return}state.images.forEach(x=>URL.revokeObjectURL(x.url));state.images=files.map(file=>({file,url:URL.createObjectURL(file)}));state.status='已选择截图，点击开始识别。';onRender()};$('#ocr-start').onclick=recognize;$('#ocr-cancel').onclick=()=>{state.cancel=true;status('正在停止识别…');state.stop?.();state.worker?.terminate().catch(()=>{});}}
refreshReview();}
